import logging

from taf.fdsw.rc.schemas.FDSW19A.autoconnection_parameters_builder_19a import Validator
from taf.fdsw.rc.schemas.FDSW23C.autoconnection_parameters_builder_23c import AutoconnectionParametersBuilder23C
logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class AutoconnectionParametersBuilder24B(AutoconnectionParametersBuilder23C):
    def __init__(self, **kwargs):
        self.protocol_parameters = self._get_protocol_parameters(**kwargs)
        super(AutoconnectionParametersBuilder24B, self).__init__(**kwargs)
        if "identification_entity_ip_address" in kwargs:
            identification_entity_ip_address = kwargs["identification_entity_ip_address"]
            self.management_plane_parameters.update(
                identServerIpAddress=Validator.validate_param(
                    "identification_entity_ip_address",
                    identification_entity_ip_address,
                    (identification_entity_ip_address is None or Validator.validate_ip_address(identification_entity_ip_address)),
                )
            )

    def _get_protocol_parameters(self, **kwargs):
        protocol_parameters = {}
        if 'protocol' in kwargs:
            logger.debug("protocol is deprecated from FDSW24B")
        return protocol_parameters

    def as_dict(self):
        attributes = super(AutoconnectionParametersBuilder24B, self).as_dict()
        if self.protocol_parameters:
            attributes.update(pnpProtocolParameters=self.protocol_parameters)
        self._del_oms_ip_address(attributes)
        return attributes

    def _del_oms_ip_address(self, attributes):
        if "managementPlaneParameters" not in attributes:
            return
        else:
            if "omsIpAddress" in attributes["managementPlaneParameters"]:
                del (attributes["managementPlaneParameters"]["omsIpAddress"])
